DECLARE
  v_category_count NUMBER;
  v_movie_count NUMBER;
BEGIN
    SELECT COUNT(*) INTO v_category_count FROM movie_user.categories;
    SELECT COUNT(*) INTO v_movie_count FROM movie_user.movies;

    IF v_category_count = 0 THEN
      COMMIT;
    END IF;

    IF v_movie_count = 0 THEN
      COMMIT;
    END IF;
END;